protocol=[
{'situacion':'Respuesta de IA pendiente o demasiado lenta','accion':'Conservar la pantalla y el contexto. No pulsar varias veces. Si termina el tiempo del bloque, anotar pendiente y comprobar historial antes de reintentar.','no_declarar':'No decir que se generó, aprobó o cargó algo sin el comprobante correspondiente.'},
{'situacion':'El proveedor informa cuota, capacidad o conectividad insuficiente','accion':'Registrar el mensaje y la etapa. Una persona autorizada puede revisar la configuración o acordar otro proveedor; si cambia el destino, revisar su prueba y autorización de envío.','no_declarar':'No cambiar silenciosamente de modelo ni atribuir éxito a un intento interrumpido.'},
{'situacion':'La respuesta no cumple el formato o contrato','accion':'Aceptar el rechazo de la plataforma; revisar la solicitud o hacer un único reintento manual si el error es definitivo y queda tiempo.','no_declarar':'No pegar una respuesta inválida a mano ni desactivar validaciones para continuar.'},
{'situacion':'La propuesta cambia el objetivo, evento o rol de una relación','accion':'Mantener el propósito original, aclarar la ambigüedad y revisar una versión nueva cuando corresponda. Si no puede justificarse, no aprobar.','no_declarar':'No afirmar que una FK válida demuestra por sí sola la interpretación comercial.'},
{'situacion':'Advertencia o requisito no disponible','accion':'Leer la limitación y decidir si el alcance restante sigue siendo útil. Si falta un requisito esencial, corregir la necesidad.','no_declarar':'Aceptar el aviso no hace que exista la capacidad ausente.'},
{'situacion':'Se pierde la respuesta durante una carga','accion':'Recuperar el expediente y leer su estado antes de iniciar cualquier otra operación. Registrar si terminó, falló o sigue en curso.','no_declarar':'No reenviar por reflejo ni anunciar conciliación por el mero paso del tiempo.'},
{'situacion':'Hay diferencia numérica, fuente equivocada o denominador incoherente','accion':'Suspender la conclusión, guardar contexto y comparar universos equivalentes. Registrar esperado y obtenido sin alterar filas ni la evidencia anterior.','no_declarar':'No ajustar las cifras para que coincidan con la guía ni sumar monedas sin evidencia.'},
{'situacion':'Se muestra una explicación o un archivo histórico como respaldo','accion':'Anunciar fuente, fecha, propuesta y ejecución histórica. Separarlo del estado del intento nuevo.','no_declarar':'Un respaldo histórico no prueba que la operación nueva se completó.'},
{'situacion':'El rol no tiene permiso o no aparece una opción','accion':'Pedir revisión a administración y registrar el permiso faltante. Continuar sólo las operaciones autorizadas.','no_declarar':'No presentar una sesión administrativa como prueba de un perfil con menos permisos.'},
{'situacion':'El chat explica algo que las cifras no sostienen','accion':'Conservar pregunta, interpretación, evidencia, respuesta y filtros. Contrastar números y cautelas antes de usar la narración.','no_declarar':'Una frase fluida no demuestra causalidad, rentabilidad, pronóstico o precisión universal.'}]
